  1→import { type KeyboardEvent, useCallback, useEffect, useRef, useState } from 'react';
  2→import { useNavigate } from 'react-router-dom';
  3→import { bytesToHex } from '@cipherbox/crypto';
  4→import { AppShell } from '../components/layout';
  5→import { LinkedMethods } from '../components/auth/LinkedMethods';
  6→import { SecurityTab } from '../components/mfa/SecurityTab';
  7→import { VaultExport } from '../components/vault/VaultExport';
  8→import { useAuth } from '../hooks/useAuth';
  9→import { useAuthStore } from '../stores/auth.store';
 10→
 11→type SettingsTabId = 'linked-methods' | 'security';
 12→
 13→const TAB_IDS: SettingsTabId[] = ['linked-methods', 'security'];
 14→
 15→function handleTabKeyDown(
 16→  e: KeyboardEvent,
 17→  activeTab: SettingsTabId,
 18→  setActiveTab: (id: SettingsTabId) => void
 19→) {
 20→  const idx = TAB_IDS.indexOf(activeTab);
 21→  let newIdx: number | null = null;
 22→  if (e.key === 'ArrowRight') newIdx = (idx + 1) % TAB_IDS.length;
 23→  else if (e.key === 'ArrowLeft') newIdx = (idx - 1 + TAB_IDS.length) % TAB_IDS.length;
 24→  else if (e.key === 'Home') newIdx = 0;
 25→  else if (e.key === 'End') newIdx = TAB_IDS.length - 1;
 26→  if (newIdx !== null) {
 27→    e.preventDefault();
 28→    setActiveTab(TAB_IDS[newIdx]);
 29→    document.getElementById(`tab-${TAB_IDS[newIdx]}`)?.focus();
 30→  }
 31→}
 32→
 33→/**
 34→ * Settings page wrapped in AppShell.
 35→ * Protected route - redirects to login if not authenticated.
 36→ *
 37→ * Tabs: Linked Methods | Security
 38→ * VaultExport shown below tabs (always visible).
 39→ */
 40→export function SettingsPage() {
 41→  const { isAuthenticated, isLoading } = useAuth();
 42→  const navigate = useNavigate();
 43→  const [activeTab, setActiveTab] = useState<SettingsTabId>('linked-methods');
 44→  const [copied, setCopied] = useState(false);
 45→  const copyTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 46→  const vaultKeypair = useAuthStore((s) => s.vaultKeypair);
 47→
 48→  const publicKeyHex = vaultKeypair?.publicKey ? `0x${bytesToHex(vaultKeypair.publicKey)}` : null;
 49→
 50→  const handleCopyPublicKey = useCallback(() => {
 51→    if (!publicKeyHex) return;
 52→    navigator.clipboard.writeText(publicKeyHex).then(() => {
 53→      setCopied(true);
 54→      if (copyTimeoutRef.current) clearTimeout(copyTimeoutRef.current);
 55→      copyTimeoutRef.current = setTimeout(() => setCopied(false), 2000);
 56→    });
 57→  }, [publicKeyHex]);
 58→
 59→  // Clean up timeout on unmount
 60→  useEffect(() => {
 61→    return () => {
 62→      if (copyTimeoutRef.current) clearTimeout(copyTimeoutRef.current);
 63→    };
 64→  }, []);
 65→
 66→  // Redirect if not authenticated
 67→  useEffect(() => {
 68→    if (!isLoading && !isAuthenticated) {
 69→      navigate('/');
 70→    }
 71→  }, [isAuthenticated, isLoading, navigate]);
 72→
 73→  // Show loading state while checking authentication
 74→  if (isLoading) {
 75→    return (
 76→      <AppShell>
 77→        <div className="loading">Loading...</div>
 78→      </AppShell>
 79→    );
 80→  }
 81→
 82→  // Don't render if not authenticated (redirect is in progress)
 83→  if (!isAuthenticated) {
 84→    return null;
 85→  }
 86→
 87→  return (
 88→    <AppShell>
 89→      <div className="settings-content">
 90→        <h2 className="settings-title">[SETTINGS]</h2>
 91→
 92→        <section className="settings-section" aria-labelledby="settings-account-heading">
 93→          <h3 id="settings-account-heading" className="settings-section-heading">
 94→            {'// account & security'}
 95→          </h3>
 96→          <p className="settings-section-description">
 97→            manage your authentication methods and account security.
 98→          </p>
 99→
100→          {/* Tab navigation */}
101→          <div className="settings-tabs" role="tablist" aria-label="Settings sections">
102→            <button
103→              type="button"
104→              role="tab"
105→              id="tab-linked-methods"
106→              aria-selected={activeTab === 'linked-methods'}
107→              aria-controls="panel-linked-methods"
108→              tabIndex={activeTab === 'linked-methods' ? 0 : -1}
109→              className={`settings-tab ${activeTab === 'linked-methods' ? 'active' : ''}`}
110→              onClick={() => setActiveTab('linked-methods')}
111→              onKeyDown={(e) => handleTabKeyDown(e, activeTab, setActiveTab)}
112→            >
113→              LINKED METHODS
114→            </button>
115→            <button
116→              type="button"
117→              role="tab"
118→              id="tab-security"
119→              aria-selected={activeTab === 'security'}
120→              aria-controls="panel-security"
121→              tabIndex={activeTab === 'security' ? 0 : -1}
122→              className={`settings-tab ${activeTab === 'security' ? 'active' : ''}`}
123→              onClick={() => setActiveTab('security')}
124→              onKeyDown={(e) => handleTabKeyDown(e, activeTab, setActiveTab)}
125→            >
126→              SECURITY
127→            </button>
128→          </div>
129→
130→          {/* Tab panels */}
131→          <div
132→            role="tabpanel"
133→            id="panel-linked-methods"
134→            aria-labelledby="tab-linked-methods"
135→            hidden={activeTab !== 'linked-methods'}
136→          >
137→            {activeTab === 'linked-methods' && <LinkedMethods />}
138→          </div>
139→
140→          <div
141→            role="tabpanel"
142→            id="panel-security"
143→            aria-labelledby="tab-security"
144→            hidden={activeTab !== 'security'}
145→          >
146→            {activeTab === 'security' && <SecurityTab />}
147→          </div>
148→        </section>
149→
150→        <section className="settings-section" style={{ marginTop: 'var(--spacing-md)' }}>
151→          <VaultExport />
152→        </section>
153→
154→        {publicKeyHex && (
155→          <section className="settings-section" style={{ marginTop: 'var(--spacing-md)' }}>
156→            <h3 className="settings-section-heading">{'// your public key'}</h3>
157→            <p className="settings-section-description">
158→              {'// share this key with others to receive shared files'}
159→            </p>
160→            <div className="settings-pubkey-box">
161→              <code className="settings-pubkey-value">{publicKeyHex}</code>
162→            </div>
163→            <button type="button" className="settings-pubkey-copy" onClick={handleCopyPublicKey}>
164→              {copied ? '--copied' : '--copy'}
165→            </button>
166→          </section>
167→        )}
168→      </div>
169→    </AppShell>
170→  );
171→}
