448→  /**
449→   * Unlink an auth method from a user account.
450→   * Cannot unlink the last remaining auth method.
451→   */
452→  async unlinkMethod(userId: string, methodId: string): Promise<void> {
453→    await this.authMethodRepository.manager.transaction(async (manager) => {
454→      // 1. Lock all auth methods for this user to prevent concurrent unlinks
455→      const methods = await manager
456→        .createQueryBuilder(AuthMethod, 'am')
457→        .setLock('pessimistic_write')
458→        .where('am.userId = :userId', { userId })
459→        .getMany();
460→
461→      // 2. Find the target method
462→      const method = methods.find((m) => m.id === methodId);
463→      if (!method) {
464→        throw new BadRequestException('Auth method not found');
465→      }
466→
467→      // 3. Cannot unlink if only 1 method remains
468→      if (methods.length <= 1) {
469→        throw new BadRequestException('Cannot unlink your last auth method');
470→      }
471→
472→      // 4. Delete the method
473→      await manager.remove(method);
474→    });
475→  }
