363→  /**
364→   * Link a wallet auth method via SIWE verification.
365→   */
366→  private async linkWalletMethod(
367→    userId: string,
368→    linkDto: LinkMethodDto
369→  ): Promise<AuthMethodResponseDto[]> {
370→    // 1. Validate required SIWE fields
371→    if (!linkDto.walletAddress || !linkDto.siweMessage || !linkDto.siweSignature) {
372→      throw new BadRequestException(
373→        'walletAddress, siweMessage, and siweSignature are required for wallet linking'
374→      );
375→    }
376→
377→    // 2. Verify SIWE signature with nonce consumption (C-01: prevent replay)
378→    const domain = this.configService.get<string>('SIWE_DOMAIN', 'localhost');
379→    const parsed = parseSiweMessage(linkDto.siweMessage);
380→    if (!parsed.nonce) {
381→      throw new BadRequestException('Invalid SIWE message: missing nonce');
382→    }
383→
384→    // Consume nonce from Redis (single-use) — same pattern as identity.controller.ts walletLogin
385→    const nonceKey = `siwe:nonce:${parsed.nonce}`;
386→    let nonceDeleted: number;
387→    try {
388→      nonceDeleted = await this.redis.del(nonceKey);
389→    } catch (err) {
390→      this.logger.error('Redis error during nonce consumption', err);
391→      throw new BadRequestException('Nonce verification failed');
392→    }
393→    if (!nonceDeleted) {
394→      throw new BadRequestException('Invalid or expired nonce');
395→    }
396→
397→    const walletAddress = await this.siweService.verifySiweMessage(
398→      linkDto.siweMessage,
399→      linkDto.siweSignature as `0x${string}`,
400→      parsed.nonce,
401→      domain
402→    );
403→
404→    // 3. Hash the wallet address for lookup
405→    const addressHash = this.siweService.hashWalletAddress(walletAddress);
406→
407→    // 4. Check cross-account collision: same wallet linked to a different user
408→    const crossAccountMethod = await this.authMethodRepository.findOne({
409→      where: {
410→        type: 'wallet',
411→        identifierHash: addressHash,
412→        userId: Not(userId),
413→      },
414→    });
415→
416→    if (crossAccountMethod) {
417→      throw new BadRequestException('This wallet is already linked to another account');
418→    }
419→
420→    // 5. Check if this wallet is already linked to this user
421→    const existingMethod = await this.authMethodRepository.findOne({
422→      where: {
423→        userId,
424→        type: 'wallet',
425→        identifierHash: addressHash,
426→      },
427→    });
428→
429→    if (existingMethod) {
430→      throw new BadRequestException('This wallet is already linked to your account');
431→    }
432→
433→    // 6. Create wallet auth method with hash + truncated display
434→    const truncated = this.siweService.truncateWalletAddress(walletAddress);
435→    await this.authMethodRepository.save({
436→      userId,
437→      type: 'wallet',
438→      identifier: addressHash,
439→      identifierHash: addressHash,
440→      identifierDisplay: truncated,
441→      lastUsedAt: new Date(),
442→    });
443→
444→    // 7. Return updated list of methods
445→    return this.getLinkedMethods(userId);
446→  }
