 64→    });
 65→
 66→    // 2b. Placeholder publicKey resolution for Core Kit identity provider.
 67→    // When a user first authenticates via CipherBox identity provider,
 68→    // they get a placeholder publicKey ('pending-core-kit-{userId}').
 69→    // After Core Kit login, the client calls /auth/login with the REAL publicKey.
 70→    // We need to find the placeholder user and update their publicKey.
 71→    if (!user) {
 72→      const verifierId = payload.verifierId || payload.sub;
 73→      if (verifierId) {
 74→        const placeholderUser = await this.userRepository.findOne({
 75→          where: { publicKey: Like(`pending-core-kit-${verifierId}%`) },
 76→        });
 77→        if (placeholderUser) {
 78→          this.logger.log(`Resolving placeholder publicKey for user ${placeholderUser.id}`);
 79→          placeholderUser.publicKey = loginDto.publicKey;
 80→          user = await this.userRepository.save(placeholderUser);
 81→        }
 82→      }
 83→    }
 84→
 85→    const isNewUser = !user;
 86→    if (!user) {
 87→      user = await this.userRepository.save({
 88→        publicKey: loginDto.publicKey,
 89→      });
 90→    }
 91→
 92→    // 3. Find or create auth method
 93→    // The identity controller already created the auth method
 94→    // (with the correct type: 'google', 'email', or 'wallet'). Look up by
 95→    // userId + identifierHash to avoid creating duplicates with a hardcoded type.
 96→    let authMethod: AuthMethod | null;
 97→
 98→    const identifier = payload.email || payload.sub;
 99→    if (!identifier) {
100→      this.logger.warn('CipherBox JWT missing both email and sub claims');
101→      throw new UnauthorizedException('Invalid identity token: missing identifier');
102→    }
103→    const identifierHash = this.siweService.hashIdentifier(identifier);
104→    authMethod = await this.authMethodRepository.findOne({
105→      where: { userId: user.id, identifierHash },
106→    });
107→    if (!authMethod) {
108→      // Fallback: find any auth method for this user (identity controller should have created one)
109→      authMethod = await this.authMethodRepository.findOne({
110→        where: { userId: user.id },
111→      });
112→    }
113→    if (!authMethod) {
114→      // Safety net: create auth method if identity controller didn't (shouldn't happen in practice)
115→      // All logins go through loginType='corekit' now, but infer type from identifier format
116→      const inferredType = identifier.startsWith('0x') ? 'wallet' : 'email';
117→      const display =
118→        inferredType === 'wallet'
119→          ? this.siweService.truncateWalletAddress(identifier)
120→          : this.siweService.truncateEmail(identifier);
121→      authMethod = await this.authMethodRepository.save({
122→        userId: user.id,
123→        type: inferredType,
124→        identifier: identifierHash,
125→        identifierHash,
126→        identifierDisplay: display,
127→      });
128→    }
129→
130→    // 4. Update last used timestamp
131→    authMethod.lastUsedAt = new Date();
132→    await this.authMethodRepository.save(authMethod);
133→
134→    // 5. Create tokens
135→    const tokens = await this.tokenService.createTokens(user.id, user.publicKey);
136→
137→    return {
138→      accessToken: tokens.accessToken,
139→      refreshToken: tokens.refreshToken,
140→      isNewUser,
141→    };
142→  }
