144→  /**
145→   * Verify a CipherBox-issued JWT for Core Kit login flow.
146→   * Since we are the identity provider, we verify against our own JWKS.
147→   */
148→  private async verifyCipherBoxJwt(
149→    idToken: string
150→  ): Promise<{ sub?: string; verifierId?: string; email?: string }> {
151→    try {
152→      const jwksData = this.jwtIssuerService.getJwksData();
153→      const jwks = jose.createLocalJWKSet(jwksData);
154→      const { payload } = await jose.jwtVerify(idToken, jwks, {
155→        issuer: 'cipherbox',
156→        audience: 'web3auth',
157→        algorithms: ['RS256'],
158→      });
159→      return {
160→        sub: payload.sub,
161→        verifierId: payload.sub,
162→        email: payload.email as string | undefined,
163→      };
164→    } catch (error) {
165→      this.logger.warn(
166→        `CipherBox JWT verification failed: ${error instanceof Error ? error.message : 'unknown'}`
167→      );
168→      throw new UnauthorizedException('Invalid CipherBox identity token');
169→    }
170→  }
171→
172→  async refresh(
173→    refreshToken: string,
174→    userId: string,
175→    publicKey: string
176→  ): Promise<RefreshServiceResult> {
177→    const tokens = await this.tokenService.rotateRefreshToken(refreshToken, userId, publicKey);
178→
179→    return {
180→      accessToken: tokens.accessToken,
181→      refreshToken: tokens.refreshToken,
182→    };
183→  }
184→
185→  async logout(userId: string): Promise<LogoutResponseDto> {
186→    await this.tokenService.revokeAllUserTokens(userId);
187→    return { success: true };
188→  }
189→
190→  /**
191→   * Permanently delete a user account and all associated data.
192→   * ON DELETE CASCADE on all FK references to users.id handles
193→   * cleanup of auth_methods, refresh_tokens, vaults, pinned_cids,
194→   * folder_ipns, ipns_republish_schedule, shares, share_keys, and share_invites.
195→   */
196→  async deleteAccount(userId: string): Promise<{ success: boolean }> {
197→    const result = await this.userRepository.delete(userId);
198→    if (result.affected === 0) {
199→      throw new BadRequestException('Account not found');
200→    }
201→    this.logger.log(`Account deleted: userId=${userId}`);
202→    return { success: true };
203→  }
204→
205→  /**
206→   * Refresh tokens by searching for the matching refresh token across all users.
207→   * This allows refresh without requiring the (possibly expired) access token.
208→   */
209→  async refreshByToken(refreshToken: string): Promise<RefreshServiceResult> {
210→    // Find candidate tokens by prefix for O(1) lookup instead of O(N) Argon2 scan
211→    const prefix = refreshToken.substring(0, 16);
212→    const tokens = await this.refreshTokenRepository.find({
213→      where: {
214→        tokenPrefix: prefix,
215→        revokedAt: IsNull(),
216→      },
217→      relations: ['user'],
218→    });
219→
220→    // Find matching token by verifying against hashes
221→    let validToken: RefreshToken | null = null;
222→    for (const token of tokens) {
223→      // Skip expired tokens
224→      if (token.expiresAt < new Date()) {
225→        continue;
226→      }
227→      try {
228→        if (await argon2.verify(token.tokenHash, refreshToken)) {
229→          validToken = token;
230→          break;
231→        }
232→      } catch {
233→        // argon2.verify throws on invalid hash format, continue checking
234→        continue;
235→      }
236→    }
237→
238→    if (!validToken) {
239→      throw new UnauthorizedException('Invalid or expired refresh token');
240→    }
241→
242→    // Revoke old token
243→    validToken.revokedAt = new Date();
244→    await this.refreshTokenRepository.save(validToken);
245→
246→    // Create new tokens
247→    const newTokens = await this.tokenService.createTokens(
248→      validToken.userId,
249→      validToken.user.publicKey
250→    );
251→
252→    // Look up user's email from their most recently used auth method
253→    // (covers both email and google auth methods)
254→    const emailMethod = await this.authMethodRepository.findOne({
255→      where: [
256→        { userId: validToken.userId, type: 'email' },
257→        { userId: validToken.userId, type: 'google' },
258→      ],
259→      order: { lastUsedAt: 'DESC' },
260→    });
261→
262→    return {
263→      accessToken: newTokens.accessToken,
264→      refreshToken: newTokens.refreshToken,
265→      // H-09: Fall back to undefined instead of leaking raw identifier hash
266→      email: emailMethod?.identifierDisplay || undefined,
267→    };
268→  }
269→
270→  /**
271→   * Get all linked auth methods for a user.
272→   * Returns identifierDisplay (human-readable) for all method types.
273→   * Falls back to identifier if identifierDisplay is not set.
274→   */
275→  async getLinkedMethods(userId: string): Promise<AuthMethodResponseDto[]> {
276→    const methods = await this.authMethodRepository.find({
277→      where: { userId },
278→      order: { createdAt: 'ASC' },
279→    });
280→
281→    return methods.map((method) => ({
282→      id: method.id,
283→      type: method.type,
284→      // H-09: Fall back to '[redacted]' instead of leaking raw identifier hash
285→      identifier: method.identifierDisplay || '[redacted]',
286→      lastUsedAt: method.lastUsedAt,
287→      createdAt: method.createdAt,
288→    }));
289→  }
290→
291→  /**
292→   * Link a new auth method to an existing user account.
293→   *
294→   * For Google/email: verifies CipherBox-issued JWT to confirm ownership of the new method.
295→   * For wallet: verifies SIWE message+signature to confirm wallet ownership.
296→   *
297→   * Cross-account collision: if the auth method already belongs to a different user,
298→   * a BadRequestException is thrown (user must unlink from the other account first).
299→   */
300→  async linkMethod(userId: string, linkDto: LinkMethodDto): Promise<AuthMethodResponseDto[]> {
301→    // 1. Get the user
302→    const user = await this.userRepository.findOne({ where: { id: userId } });
303→    if (!user) {
304→      throw new UnauthorizedException('User not found');
305→    }
306→
307→    const authMethodType = linkDto.loginType;
308→
309→    if (authMethodType === 'wallet') {
310→      // Wallet linking: verify SIWE message + signature
311→      return this.linkWalletMethod(userId, linkDto);
312→    }
313→
314→    // Google/email linking: verify CipherBox-issued JWT
315→    return this.linkJwtMethod(userId, linkDto);
316→  }
317→
318→  /**
319→   * Link a Google or email auth method via CipherBox JWT verification.
320→   */
321→  private async linkJwtMethod(
322→    userId: string,
323→    linkDto: LinkMethodDto
324→  ): Promise<AuthMethodResponseDto[]> {
325→    // 1. Verify the CipherBox-issued JWT
326→    const payload = await this.verifyCipherBoxJwt(linkDto.idToken);
327→
328→    // 2. Determine type and identifier, hash for lookup
329→    const authMethodType = linkDto.loginType;
330→    const identifier = payload.email || payload.sub;
331→    if (!identifier) {
332→      throw new BadRequestException('Cannot determine identifier from JWT');
333→    }
334→    const identifierHash = this.siweService.hashIdentifier(identifier);
335→
336→    // 3. Check cross-account collision: same identifier linked to a different user
337→    const crossAccountMethod = await this.authMethodRepository.findOne({
338→      where: {
339→        type: authMethodType,
340→        identifierHash,
341→        userId: Not(userId),
342→      },
343→    });
344→
345→    if (crossAccountMethod) {
346→      throw new BadRequestException(
347→        `This ${authMethodType === 'google' ? 'Google account' : 'email'} is already linked to another account`
348→      );
349→    }
350→
351→    // 4. Check if this exact method is already linked to this user
352→    const existingMethod = await this.authMethodRepository.findOne({
353→      where: {
354→        userId,
355→        type: authMethodType,
356→        identifierHash,
357→      },
358→    });
359→
360→    if (existingMethod) {
361→      throw new BadRequestException('This auth method is already linked to your account');
362→    }
363→
364→    // 5. Create new AuthMethod entity with hashed identifier
365→    await this.authMethodRepository.save({
366→      userId,
367→      type: authMethodType,
368→      identifier: identifierHash,
369→      identifierHash,
370→      identifierDisplay: payload.email ? this.siweService.truncateEmail(payload.email) : identifier,
371→      lastUsedAt: new Date(),
372→    });
373→
374→    // 6. Return updated list of methods
375→    return this.getLinkedMethods(userId);
376→  }
377→
378→  /**
379→   * Link a wallet auth method via SIWE verification.
380→   */
381→  private async linkWalletMethod(
382→    userId: string,
383→    linkDto: LinkMethodDto
384→  ): Promise<AuthMethodResponseDto[]> {
385→    // 1. Validate required SIWE fields
386→    if (!linkDto.walletAddress || !linkDto.siweMessage || !linkDto.siweSignature) {
387→      throw new BadRequestException(
388→        'walletAddress, siweMessage, and siweSignature are required for wallet linking'
389→      );
390→    }
391→
392→    // 2. Verify SIWE signature with nonce consumption (C-01: prevent replay)
393→    const domain = this.configService.get<string>('SIWE_DOMAIN', 'localhost');
394→    const parsed = parseSiweMessage(linkDto.siweMessage);
395→    if (!parsed.nonce) {
396→      throw new BadRequestException('Invalid SIWE message: missing nonce');
397→    }
398→
399→    // Consume nonce from Redis (single-use) — same pattern as identity.controller.ts walletLogin
400→    const nonceKey = `siwe:nonce:${parsed.nonce}`;
401→    let nonceDeleted: number;
402→    try {
403→      nonceDeleted = await this.redis.del(nonceKey);
404→    } catch (err) {
405→      this.logger.error('Redis error during nonce consumption', err);
406→      throw new BadRequestException('Nonce verification failed');
407→    }
408→    if (!nonceDeleted) {
409→      throw new BadRequestException('Invalid or expired nonce');
410→    }
411→
412→    const walletAddress = await this.siweService.verifySiweMessage(
413→      linkDto.siweMessage,
414→      linkDto.siweSignature as `0x${string}`,
415→      parsed.nonce,
416→      domain
417→    );
418→
419→    // 3. Hash the wallet address for lookup
420→    const addressHash = this.siweService.hashWalletAddress(walletAddress);
421→
422→    // 4. Check cross-account collision: same wallet linked to a different user
423→    const crossAccountMethod = await this.authMethodRepository.findOne({
424→      where: {
425→        type: 'wallet',
426→        identifierHash: addressHash,
427→        userId: Not(userId),
428→      },
429→    });
430→
431→    if (crossAccountMethod) {
432→      throw new BadRequestException('This wallet is already linked to another account');
433→    }
434→
435→    // 5. Check if this wallet is already linked to this user
436→    const existingMethod = await this.authMethodRepository.findOne({
437→      where: {
438→        userId,
439→        type: 'wallet',
440→        identifierHash: addressHash,
441→      },
442→    });
443→
444→    if (existingMethod) {
445→      throw new BadRequestException('This wallet is already linked to your account');
446→    }
447→
448→    // 6. Create wallet auth method with hash + truncated display
449→    const truncated = this.siweService.truncateWalletAddress(walletAddress);
450→    await this.authMethodRepository.save({
451→      userId,
452→      type: 'wallet',
453→      identifier: addressHash,
454→      identifierHash: addressHash,
455→      identifierDisplay: truncated,
456→      lastUsedAt: new Date(),
457→    });
458→
459→    // 7. Return updated list of methods
460→    return this.getLinkedMethods(userId);
461→  }
462→
463→  /**
464→   * Unlink an auth method from a user account.
465→   * Cannot unlink the last remaining auth method.
466→   */
467→  async unlinkMethod(userId: string, methodId: string): Promise<void> {
468→    await this.authMethodRepository.manager.transaction(async (manager) => {
469→      // 1. Lock all auth methods for this user to prevent concurrent unlinks
470→      const methods = await manager
471→        .createQueryBuilder(AuthMethod, 'am')
472→        .setLock('pessimistic_write')
473→        .where('am.userId = :userId', { userId })
474→        .getMany();
475→
476→      // 2. Find the target method
477→      const method = methods.find((m) => m.id === methodId);
478→      if (!method) {
479→        throw new BadRequestException('Auth method not found');
480→      }
481→
482→      // 3. Cannot unlink if only 1 method remains
483→      if (methods.length <= 1) {
484→        throw new BadRequestException('Cannot unlink your last auth method');
485→      }
486→
487→      // 4. Delete the method
488→      await manager.remove(method);
489→    });
490→  }
491→
492→  /**
493→   * Test-only login that bypasses Core Kit entirely.
494→   * Guarded by TEST_LOGIN_SECRET env var — never available in production.
495→   *
496→   * Creates/finds user by email, generates a deterministic secp256k1 keypair,
497→   * and issues tokens. Returns the keypair so E2E tests can initialize vaults.
498→   */
499→  async testLogin(
500→    email: string,
501→    secret: string
502→  ): Promise<{
503→    accessToken: string;
504→    refreshToken: string;
505→    isNewUser: boolean;
506→    publicKeyHex: string;
507→    privateKeyHex: string;
508→  }> {
509→    // 1. Defense-in-depth: never allow in production regardless of env var
510→    const nodeEnv = this.configService.get<string>('NODE_ENV');
511→    if (nodeEnv === 'production') {
512→      throw new ForbiddenException('Test login is not available in production');
513→    }
514→
515→    // 2. Validate TEST_LOGIN_SECRET with timing-safe comparison
516→    const expectedSecret = this.configService.get<string>('TEST_LOGIN_SECRET');
517→    if (!expectedSecret) {
518→      throw new ForbiddenException('Test login is not enabled');
519→    }
520→    const secretBuf = Buffer.from(secret);
521→    const expectedBuf = Buffer.from(expectedSecret);
522→    if (secretBuf.length !== expectedBuf.length || !timingSafeEqual(secretBuf, expectedBuf)) {
523→      throw new UnauthorizedException('Invalid test login secret');
524→    }
525→
526→    // 2. Generate deterministic secp256k1 keypair from email
527→    const { publicKeyHex, privateKeyHex } = this.generateDeterministicKeypair(email);
528→
529→    // 3. Find or create user by email (hash-based lookup)
530→    const normalizedEmail = email.toLowerCase().trim();
531→    const identifierHash = this.siweService.hashIdentifier(normalizedEmail);
532→
533→    const existingMethod = await this.authMethodRepository.findOne({
534→      where: { type: 'email', identifierHash },
535→      relations: ['user'],
536→    });
537→
538→    let user: User;
539→    let isNewUser = false;
540→
541→    if (existingMethod) {
542→      user = existingMethod.user;
543→      // Update publicKey to match deterministic keypair (may differ from Core Kit key)
544→      if (user.publicKey !== publicKeyHex) {
545→        user.publicKey = publicKeyHex;
546→        await this.userRepository.save(user);
547→      }
548→      existingMethod.lastUsedAt = new Date();
549→      await this.authMethodRepository.save(existingMethod);
550→    } else {
551→      isNewUser = true;
552→      user = await this.userRepository.save({ publicKey: publicKeyHex });
553→      await this.authMethodRepository.save({
554→        userId: user.id,
555→        type: 'email',
556→        identifier: identifierHash,
557→        identifierHash,
558→        identifierDisplay: this.siweService.truncateEmail(normalizedEmail),
559→        lastUsedAt: new Date(),
560→      });
561→    }
562→
563→    // 4. Issue tokens
564→    const tokens = await this.tokenService.createTokens(user.id, user.publicKey);
565→
566→    this.logger.log(`Test login: userId=${user.id}, isNew=${isNewUser}`);
567→
568→    return {
569→      accessToken: tokens.accessToken,
570→      refreshToken: tokens.refreshToken,
571→      isNewUser,
572→      publicKeyHex,
573→      privateKeyHex,
574→    };
575→  }
576→
577→  /**
578→   * Generate a deterministic secp256k1 keypair from an email address.
579→   * Same email always produces the same keypair, enabling consistent
580→   * vault encryption across test runs.
581→   */
582→  private generateDeterministicKeypair(email: string): {
583→    publicKeyHex: string;
584→    privateKeyHex: string;
585→  } {
586→    // Derive 32-byte private key from email via SHA-256
587→    const seed = createHash('sha256')
588→      .update(`cipherbox-test-keypair:${email.toLowerCase().trim()}`)
589→      .digest();
590→
591→    // Ensure the seed is a valid secp256k1 private key (must be in [1, n-1])
592→    const n = BigInt('0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141');
593→    let keyInt = BigInt('0x' + seed.toString('hex'));
594→    keyInt = (keyInt % (n - 1n)) + 1n;
595→    const privateKeyHex = keyInt.toString(16).padStart(64, '0');
596→
597→    const ecdh = createECDH('secp256k1');
598→    ecdh.setPrivateKey(Buffer.from(privateKeyHex, 'hex'));
599→    const publicKeyHex = ecdh.getPublicKey().toString('hex'); // 65 bytes uncompressed
600→
601→    return { publicKeyHex, privateKeyHex };
602→  }
603→}
